//! 🧿 Remodel mutation — `CreateGcp`: brings a new id-keyed ground control point into existence
//! (id pre-generated by the caller via `next_remodel_id("gcp")`).

use crate::artifacts::remodel::{GroundControlPoint, RemodelSnapshot};
use crate::artifacts::remodel::diff::{RemodelDiff, RemodelGcpList};
use crate::artifacts::remodel::mutations::RemodelMutation;
use serde::{Deserialize, Serialize};
use semio_framework_value_derive::{FromValue, ToValue};

//#region 🔖️Mutation
/// 🧿 `create-gcp` payload.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize, ToValue, FromValue, dsl::DslRecord, dsl::MutationLeaf)]
#[mutation_leaf(contract = ::protocol)]
#[value(rename_all = "camelCase")]
#[serde(rename_all = "camelCase")]
#[dsl(keyword = "create-gcp")]
pub struct CreateGcp {
    #[dsl(block)]
    pub gcp: GroundControlPoint,
}

/// 🏗️ Builder — wraps the payload in its dispatch variant.
pub fn create_gcp(gcp: GroundControlPoint) -> RemodelMutation {
    RemodelMutation::CreateGcp(CreateGcp { gcp })
}

impl protocol::MutationKind<RemodelSnapshot, RemodelMutation> for CreateGcp {
    const SEMANTICS: protocol::SemanticDescriptor = protocol::SemanticDescriptor { verb: "create", entity: "gcp", kind: "create-gcp", record: "CreatedGcp" };

    async fn diff(&self, base: &RemodelSnapshot) -> protocol::MutationOutcome<RemodelDiff> {
        super::diff::diff(self, base)
    }
    async fn inverse(&self, base: &RemodelSnapshot) -> Vec<RemodelMutation> {
        super::inverse::inverse(self, base)
    }
    async fn label(&self) -> String {
        format!("Create GCP \"{}\"", self.gcp.id)
    }
    async fn target(&self) -> Vec<String> {
        vec![self.gcp.id.clone()]
    }
}
//#endregion 🔖️Mutation
